function readSettings(settings) {
  const { imageUrl, imageMimeType, from, to, subject, html } = settings;
  const email = /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?$/;
  if (typeof from !== "string" || typeof to !== "string" || !email.test(from) || !email.test(to)) {
    throw new Error("Set one sender address and one recipient address");
  }
  if (typeof subject !== "string" || /[\r\n\0]/.test(subject)) {
    throw new Error("Set a subject without line breaks");
  }
  if (
    typeof imageUrl !== "string" ||
    !/^https:\/\/[a-z0-9.-]+(?::\d+)?(?:[/?#][^\s]*)?$/i.test(imageUrl)
  ) {
    throw new Error("Set a public HTTPS image URL without embedded credentials");
  }
  if (typeof imageMimeType !== "string" || !/^image\/[a-z0-9.+-]+$/.test(imageMimeType)) {
    throw new Error("Set the image media type, such as image/jpeg or image/png");
  }
  if (
    typeof html !== "string" ||
    !/\bsrc\s*=\s*(?:"cid:image1"|'cid:image1'|cid:image1(?=[\s>]))/i.test(html)
  ) {
    throw new Error("Keep the cid:image1 image reference in the HTML body");
  }
  return {
    imageUrl: imageUrl.replace(/^https:/i, "https:"),
    imageMimeType,
    from,
    to,
    subject,
    html,
  };
}
return [{ json: readSettings($input.first().json) }];

function encodeMessage(settings, imageBase64, mediaType) {
  if (mediaType !== settings.imageMimeType) {
    throw new Error("The downloaded image media type differs from the configured type");
  }
  if (typeof imageBase64 !== "string" || !imageBase64) {
    throw new Error("The cloud image download returned no bytes");
  }
  const imageBytes = Buffer.from(imageBase64, "base64");
  if (!imageBytes.length || imageBytes.toString("base64") !== imageBase64) {
    throw new Error("The image bytes are not valid Base64");
  }
  if (imageBytes.length > 25_000_000) {
    throw new Error("The image exceeds the 25 MB email limit");
  }

  const words = [];
  let chunk = "";
  for (const character of settings.subject) {
    if (Buffer.byteLength(chunk + character, "utf8") > 42) {
      words.push(chunk);
      chunk = "";
    }
    chunk += character;
  }
  if (chunk) words.push(chunk);
  const subject = words
    .map((word) => "=?UTF-8?B?" + Buffer.from(word, "utf8").toString("base64") + "?=")
    .join("\r\n ");

  const wrap = (base64) => base64.match(/.{1,76}/g).join("\r\n");
  const boundary = "openflow-inline-image";
  const mime = [
    "From: " + settings.from,
    "To: " + settings.to,
    "Subject: " + subject,
    "MIME-Version: 1.0",
    'Content-Type: multipart/related; type="text/html"; boundary="' + boundary + '"',
    "",
    "--" + boundary,
    "Content-Type: text/html; charset=UTF-8",
    "Content-Transfer-Encoding: base64",
    "",
    wrap(Buffer.from(settings.html, "utf8").toString("base64")),
    "",
    "--" + boundary,
    "Content-Type: " + mediaType,
    "Content-Transfer-Encoding: base64",
    "Content-Disposition: inline",
    "Content-ID: <image1>",
    "",
    wrap(imageBase64),
    "",
    "--" + boundary + "--",
    "",
  ].join("\r\n");
  if (Buffer.byteLength(mime, "utf8") > 35_000_000) {
    throw new Error("The encoded email exceeds the Gmail MIME size limit");
  }
  return {
    raw: Buffer.from(mime, "utf8")
      .toString("base64")
      .replace(/\+/g, "-")
      .replace(/\//g, "_")
      .replace(/=+$/, ""),
  };
}
const settings = $("Validate message settings").first().json;
const media = $("Get image").first().binary?.data?.mimeType?.split(";")[0]?.trim()?.toLowerCase();
return [{ json: encodeMessage(settings, $input.first().json.imageBase64, media) }];

function readReceipt(messageId, threadId) {
  if (typeof messageId !== "string" || !messageId.trim()) {
    throw new Error("Gmail did not return a message ID");
  }
  return {
    messageId,
    threadId: typeof threadId === "string" && threadId ? threadId : null,
  };
}
const { id, threadId } = $input.first().json;
return [{ json: readReceipt(id, threadId) }];
